package com.rewang.app;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import java.util.*;import java.io.*;

/** Offline, native quote directory. Real names/codes; explicitly synthetic prices. */
public class QuotesActivity extends Activity {
 private final List<JSONObject> all=new ArrayList<>();private final Set<String> watch=new HashSet<>();
 private LinearLayout content,list,nav;private String market="A股",section="行情",sector="全部行业",board="全部板块",query="",order="涨幅榜";private EditText search;
 protected void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.activity_main);content=findViewById(R.id.content);nav=findViewById(R.id.navigation);findViewById(R.id.root).setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});((TextView)findViewById(R.id.mode)).setText("真实名称 · 模拟报价");try(InputStream in=getAssets().open("quotes-demo.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONArray rows=new JSONObject(out.toString("UTF-8")).getJSONArray("rows");for(int i=0;i<rows.length();i++)all.add(rows.getJSONObject(i));watch.addAll(getPreferences(0).getStringSet("watch",new HashSet<>(Arrays.asList("600519.SH","300750.SZ","00700.HK","AAPL"))));}catch(Exception e){new AlertDialog.Builder(this).setMessage("演示数据读取失败："+e.getMessage()).setPositiveButton("返回",(d,w)->finish()).show();return;}for(String p:new String[]{"行情","排行","行业","自选","研究"}){Button b=new Button(this);b.setText(p);b.setAllCaps(false);b.setTextSize(11);b.setBackgroundColor(Color.TRANSPARENT);nav.addView(b,new LinearLayout.LayoutParams(0,-1,1));b.setOnClickListener(v->{if(p.equals("研究")){finish();return;}section=p;render();});}render();}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private int color(double v){return v>0?0xffb6634c:v<0?0xff557d72:0xff8c9690;}private String num(double v){return String.format(Locale.US,"%,.2f",v);}private String pct(double v){return (v>0?"+":"")+String.format(Locale.US,"%.2f%%",v);}private String amount(double v){return v>=1e8?num(v/1e8)+"亿":v>=1e4?num(v/1e4)+"万":num(v);}
 private TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(4),1);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 private void addLabel(String s,int size,int color,boolean bold){TextView t=label(s,size,color,bold);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(15);content.addView(t,p);}
 private GradientDrawable bg(boolean selected){GradientDrawable g=new GradientDrawable();g.setColor(selected?0xffeae4d8:Color.TRANSPARENT);g.setCornerRadius(dp(4));return g;}
 private void line(LinearLayout target){View v=new View(this);v.setBackgroundColor(0xffe0d9cd);target.addView(v,new LinearLayout.LayoutParams(-1,dp(1)));}
 private void watch(String id){if(watch.contains(id))watch.remove(id);else watch.add(id);getPreferences(0).edit().putStringSet("watch",new HashSet<>(watch)).apply();renderList();}
 private void render(){content.removeAllViews();for(int i=0;i<nav.getChildCount();i++){Button b=(Button)nav.getChildAt(i);b.setTextColor(b.getText().equals(section)?0xffa66a4e:0xff72828b);}addLabel("MARKET DIRECTORY / "+section,10,0xffa18167,false);TextView h=label("看全市场，再看一家。",26,0xff2d4656,true);h.setTypeface(Typeface.SERIF);content.addView(h);addLabel("44 支真实名称标的\n固定演示截面 2026-11-13 · 非实际行情",11,0xff91978e,false);
 LinearLayout markets=new LinearLayout(this);for(String m:new String[]{"A股","港股","美股"}){Button b=new Button(this);b.setText(m);b.setTextSize(12);b.setTextColor(0xff2d5366);b.setBackground(bg(m.equals(market)));markets.addView(b,new LinearLayout.LayoutParams(0,dp(44),1));b.setOnClickListener(v->{market=m;sector="全部行业";board="全部板块";query="";render();});}content.addView(markets);
 search=new EditText(this);search.setText(query);search.setSingleLine(true);search.setTextSize(13);search.setTextColor(0xff2d5366);search.setHint("名称 / 代码 / 拼音首字母");search.setContentDescription("搜索股票");LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(55));sp.topMargin=dp(15);sp.bottomMargin=dp(15);content.addView(search,sp);
 List<String> sectors=new ArrayList<>(Collections.singletonList("全部行业")),boards=new ArrayList<>(Collections.singletonList("全部板块"));for(JSONObject s:all)if(s.optString("market").equals(market)){if(!sectors.contains(s.optString("sector")))sectors.add(s.optString("sector"));if(!boards.contains(s.optString("board")))boards.add(s.optString("board"));}
 LinearLayout filters=new LinearLayout(this);Spinner industry=spinner(sectors,sector),boardFilter=spinner(boards,board);filters.addView(industry,new LinearLayout.LayoutParams(0,dp(48),1));filters.addView(boardFilter,new LinearLayout.LayoutParams(0,dp(48),1));content.addView(filters);Spinner ranks=spinner(Arrays.asList("涨幅榜","跌幅榜","成交额榜","换手率榜","振幅榜"),order);content.addView(ranks,new LinearLayout.LayoutParams(-1,dp(48)));
 addLabel("报价、排名、走势与交易状态均为构造的演示数据。各市场按自身币种展示，成交额不跨币种混排。",10,0xff9a9586,false);list=new LinearLayout(this);list.setOrientation(1);content.addView(list);renderList();
 search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int c){query=s.toString();renderList();}public void afterTextChanged(Editable e){}});
 industry.setOnItemSelectedListener(listener(v->{sector=v;renderList();}));boardFilter.setOnItemSelectedListener(listener(v->{board=v;renderList();}));ranks.setOnItemSelectedListener(listener(v->{order=v;renderList();}));
 Button live=new Button(this);live.setText("实时观察 / 六家美股公开数据 →");live.setTextSize(12);live.setTextColor(0xff2d5366);live.setBackground(bg(false));content.addView(live,new LinearLayout.LayoutParams(-1,dp(52)));live.setOnClickListener(v->startActivity(new Intent(this,MarketActivity.class)));}
 private interface Selected {void run(String value);}private AdapterView.OnItemSelectedListener listener(Selected cb){return new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){cb.run(p.getItemAtPosition(position).toString());}};}private Spinner spinner(List<String> options,String value){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,options));s.setSelection(Math.max(0,options.indexOf(value)));return s;}
 private String sortKey(){return order.equals("成交额榜")?"amount":order.equals("换手率榜")?"turnover":order.equals("振幅榜")?"amplitude":"changePct";}
 private List<JSONObject> filtered(){List<JSONObject> rows=new ArrayList<>();String q=query.trim().toLowerCase(Locale.ROOT);for(JSONObject s:all){if(!s.optString("market").equals(market))continue;if(!sector.equals("全部行业")&&!sector.equals(s.optString("sector")))continue;if(!board.equals("全部板块")&&!board.equals(s.optString("board")))continue;if(section.equals("自选")&&!watch.contains(s.optString("id")))continue;String hay=(s.optString("name")+s.optString("code")+s.optString("initials")+s.optString("en")).toLowerCase(Locale.ROOT);if(!hay.contains(q))continue;rows.add(s);}rows.sort((a,b)->{if(a.optString("status").equals("停牌")&&!b.optString("status").equals("停牌"))return 1;if(b.optString("status").equals("停牌")&&!a.optString("status").equals("停牌"))return -1;return Double.compare(a.optDouble(sortKey()),b.optDouble(sortKey()))*(order.equals("跌幅榜")?1:-1);});return rows;}
 private void renderList(){if(list==null)return;list.removeAllViews();if(section.equals("行业")){Map<String,List<JSONObject>> groups=new TreeMap<>();for(JSONObject s:filtered())groups.computeIfAbsent(s.optString("sector"),k->new ArrayList<>()).add(s);for(Map.Entry<String,List<JSONObject>> entry:groups.entrySet()){double sum=0;int n=0;for(JSONObject s:entry.getValue())if(!s.optString("status").equals("停牌")){sum+=s.optDouble("changePct");n++;}double mean=n==0?0:sum/n;Button b=new Button(this);b.setText(entry.getKey()+"   "+entry.getValue().size()+" 支   "+pct(mean)+"  →");b.setTextColor(color(mean));b.setTextSize(14);b.setBackground(bg(false));list.addView(b,new LinearLayout.LayoutParams(-1,dp(70)));line(list);b.setOnClickListener(v->{sector=entry.getKey();section="行情";render();});}return;}
 List<JSONObject> rows=filtered();TextView info=label(rows.size()+" 支 / "+market+" · 当前筛选排名",10,0xff989b90,false);info.setPadding(0,dp(15),0,dp(16));list.addView(info);line(list);int rank=0;for(JSONObject s:rows){final JSONObject stock=s;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(16),0,dp(16));LinearLayout left=new LinearLayout(this);left.setOrientation(1);TextView name=label((++rank)+"  "+s.optString("name"),13,0xff2d4656,true),code=label(s.optString("code")+" · "+s.optString("sector"),9,0xff979c91,false);name.setPadding(0,0,0,dp(7));left.addView(name);left.addView(code);row.addView(left,new LinearLayout.LayoutParams(0,-2,2));LinearLayout values=new LinearLayout(this);values.setOrientation(1);values.setGravity(Gravity.END);TextView price=label(num(s.optDouble("price")),17,color(s.optDouble("changePct")),false);price.setTypeface(Typeface.SERIF);String detail=s.optString("status").equals("停牌")?"停牌示例":order.equals("成交额榜")?amount(s.optDouble("amount")):order.equals("换手率榜")?pct(s.optDouble("turnover")):order.equals("振幅榜")?pct(s.optDouble("amplitude")):pct(s.optDouble("changePct"));values.addView(price);values.addView(label(detail,11,color(s.optDouble("changePct")),false));row.addView(values,new LinearLayout.LayoutParams(0,-2,1));Button star=new Button(this);star.setText(watch.contains(s.optString("id"))?"★":"☆");star.setTextSize(20);star.setTextColor(0xffac7954);star.setBackgroundColor(Color.TRANSPARENT);star.setContentDescription((watch.contains(s.optString("id"))?"取消自选":"添加自选")+s.optString("name"));row.addView(star,new LinearLayout.LayoutParams(dp(43),dp(48)));star.setOnClickListener(v->watch(stock.optString("id")));left.setOnClickListener(v->details(stock));values.setOnClickListener(v->details(stock));list.addView(row);line(list);}if(rows.isEmpty()){TextView empty=label("没有匹配的股票。\n请尝试切换市场、行业或清除搜索。",13,0xff8c978f,false);empty.setPadding(0,dp(25),0,dp(25));list.addView(empty);}}
 private void details(JSONObject s){LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(24),dp(15),dp(24),dp(20));String currency=s.optString("currency").equals("CNY")?"¥":s.optString("currency").equals("HKD")?"HK$":"US$";TextView price=label(currency+num(s.optDouble("price"))+"  "+pct(s.optDouble("changePct")),26,color(s.optDouble("changePct")),false);body.addView(price);body.addView(label("真实名称 · 模拟价格 / 2026-11-13\n"+s.optString("board")+" · "+s.optString("sector"),11,0xff9a9586,false));body.addView(new MarketChart(this,s.optJSONArray("history"),"9999-12-31"),new LinearLayout.LayoutParams(-1,dp(200)));body.addView(label("今开 "+num(s.optDouble("open"))+"    昨收 "+num(s.optDouble("previous"))+"\n最高 "+num(s.optDouble("high"))+"    最低 "+num(s.optDouble("low"))+"\n成交额 "+amount(s.optDouble("amount"))+"    换手率 "+pct(s.optDouble("turnover"))+"\n状态："+s.optString("status")+"示例\n走势图为演示数据，不是该证券真实历史。",12,0xff627984,false));ScrollView scroll=new ScrollView(this);scroll.addView(body);new AlertDialog.Builder(this).setTitle(s.optString("name")+" / "+s.optString("code")).setView(scroll).setPositiveButton(watch.contains(s.optString("id"))?"移出自选":"加入自选",(d,w)->watch(s.optString("id"))).setNegativeButton("关闭",null).show();}
}
